void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_ty0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res)
{
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 dx, dy;
    OPJ_UINT32 max_precision = 0;

    OPJ_UINT32 num_resolutions = p_cp->disto_alloc->numresolution;

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        for (resno = 0; resno < num_resolutions; ++resno) {
            dx = p_cp->disto_alloc->dx[compno][resno];
            dy = p_cp->disto_alloc->dy[compno][resno];
            if (dx > max_precision) {
                max_precision = dx;
            }
            if (dy > max_precision) {
                max_precision = dy;
            }
        }
    }

    *p_tx0 = p_cp->tx0;
    *p_ty0 = p_cp->ty0;
    *p_tx1 = p_cp->tx1;
    *p_ty1 = p_cp->ty1;
    *p_dx_min = p_cp->disto_alloc->dx_min;
    *p_dy_min = p_cp->disto_alloc->dy_min;
    *p_max_prec = max_precision;
    *p_max_res = num_resolutions;
}

void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 dx, dy;
    OPJ_UINT32 max_precision = 0;
    OPJ_UINT32 max_resolution = 0;
    OPJ_UINT32 min_prec_x = 0;
    OPJ_UINT32 min_prec_y = 0;

    OPJ_UINT32 x0, y0, x1, y1;
    x0 = p_cp->tx0;
    y0 = p_cp->ty0;
    x1 = p_cp->tx1;
    y1 = p_cp->ty1;

    *p_tx0 = (OPJ_INT32)x0;
    *p_tx1 = (OPJ_INT32)x1;
    *p_ty0 = (OPJ_INT32)y0;
    *p_ty1 = (OPJ_INT32)y1;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        opj_tcp_t *tcp = &p_cp->tcp[p_tileno];
        opj_tccp_t *tccp = &tcp->tccps[compno];

        for (resno = 1; resno < tccp->numresolutions; resno++) {
            dx = tccp->precinct_size.x;
            dy = tccp->precinct_size.y;

            if (dx < min_prec_x || min_prec_x == 0) {
                min_prec_x = dx;
            }

            if (dy < min_prec_y || min_prec_y == 0) {
                min_prec_y = dy;
            }

            if (resno > max_resolution) {
                max_resolution = resno;
            }
        }

        if (tccp->numresolutions > max_precision) {
            max_precision = tccp->numresolutions;
        }
    }

    *p_dx_min = min_prec_x;
    *p_dy_min = min_prec_y;
    *p_max_prec = max_precision;
    *p_max_res = max_resolution;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 dx, dy;
    OPJ_UINT32 max_precision = 0;
    OPJ_UINT32 max_resolution = 0;
    OPJ_UINT32 min_dx = 0;
    OPJ_UINT32 min_dy = 0;

    OPJ_UINT32 tx0, tx1, ty0, ty1;

    /* Calculate tile coordinates */
    tx0 = p_tileno % p_cp->tw * p_image->x1;
    tx1 = tx0 + p_image->x1;
    if (tx1 > p_cp->ox0 + (p_cp->tw - 1) * p_cp->tdx)
        tx1 = p_cp->ox0 + (p_cp->tw - 1) * p_cp->tdx;

    ty0 = p_tileno / p_cp->tw * p_image->y1;
    ty1 = ty0 + p_image->y1;
    if (ty1 > p_cp->oy0 + (p_cp->th - 1) * p_cp->tdy)
        ty1 = p_cp->oy0 + (p_cp->th - 1) * p_cp->tdy;

    *p_tx0 = tx0;
    *p_tx1 = tx1;
    *p_ty0 = ty0;
    *p_ty1 = ty1;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        for (resno = 0; resno < p_cp->resolution; resno++) {
            dx = p_cp->tx0[compno] + (1 << resno);
            dy = p_cp->ty0[compno] + (1 << resno);

            if (resno + 1 > max_precision)
                max_precision = resno + 1;

            if (resno + 1 > max_resolution)
                max_resolution = resno + 1;

            if (min_dx == 0 || dx < min_dx)
                min_dx = dx;

            if (min_dy == 0 || dy < min_dy)
                min_dy = dy;
        }
    }

    *p_dx_min = min_dx;
    *p_dy_min = min_dy;
    *p_max_prec = max_precision;
    *p_max_res = max_resolution;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno, OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1, OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec, OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 i, compno;
    OPJ_UINT32 num_res = 1;
    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 1;
    OPJ_UINT32 tile_w, tile_h;
    OPJ_UINT32 num_tiles_w, num_tiles_h;
    OPJ_UINT32 tile_grid_w, tile_grid_h;
    OPJ_UINT32 x0, y0;
    OPJ_UINT32 tile_width, tile_height;

    /* Calculate tile grid dimensions */
    num_tiles_w = (p_image->x1 - p_image->x0 + p_cp->tile_info->x_tiling_shift) >> p_cp->tile_info->x_tiling_shift;
    num_tiles_h = (p_image->y1 - p_image->y0 + p_cp->tile_info->y_tiling_shift) >> p_cp->tile_info->y_tiling_shift;

    tile_grid_w = (p_image->x1 - p_image->x0 + num_tiles_w - 1) / num_tiles_w;
    tile_grid_h = (p_image->y1 - p_image->y0 + num_tiles_h - 1) / num_tiles_h;

    /* Calculate tile offset */
    x0 = (p_tileno % num_tiles_w) * tile_grid_w;
    y0 = (p_tileno / num_tiles_w) * tile_grid_h;

    /* Calculate tile width and height */
    if (p_tileno % num_tiles_w == num_tiles_w - 1) {
        tile_width = p_image->x1 - p_image->x0 - x0;
    } else {
        tile_width = tile_grid_w;
    }

    if (p_tileno / num_tiles_w == num_tiles_h - 1) {
        tile_height = p_image->y1 - p_image->y0 - y0;
    } else {
        tile_height = tile_grid_h;
    }

    *p_tx0 = x0;
    *p_tx1 = x0 + tile_width;
    *p_ty0 = y0;
    *p_ty1 = y0 + tile_height;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        for (i = 1; i < p_cp->tcp->disto_alloc[compno]; i++) {
            if (p_cp->tcp->disto[compno][i].resno >= max_res) {
                max_res = p_cp->tcp->disto[compno][i].resno + 1;
            }
        }

        if (p_cp->tcp->resolutions[compno] > max_res) {
            max_res = p_cp->tcp->resolutions[compno];
        }

        if (p_cp->tcp->disto[compno][0].dx < dx_min || dx_min == 0) {
            dx_min = p_cp->tcp->disto[compno][0].dx;
        }

        if (p_cp->tcp->disto[compno][0].dy < dy_min || dy_min == 0) {
            dy_min = p_cp->tcp->disto[compno][0].dy;
        }

        if (p_cp->tcp->disto[compno][0].resno > max_prec) {
            max_prec = p_cp->tcp->disto[compno][0].resno;
        }
    }

    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_ty0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 dx, dy;
    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;
    OPJ_UINT32 tx, ty, tw, th;
    OPJ_UINT32 tileno = 0;
    OPJ_UINT32 x, y;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        OPJ_UINT32 levels = p_cp->tcp->num_resolutions;
        dx = 1;
        dy = 1;
        if (levels > max_prec) {
            max_prec = levels;
        }

        for (resno = 0; resno < levels; resno++) {
            dx <<= 1;
            dy <<= 1;
            if (resno == 0) {
                if (dx_min > dx) {
                    dx_min = dx;
                }
                if (dy_min > dy) {
                    dy_min = dy;
                }
            }
        }

        if (levels > max_res) {
            max_res = levels;
        }
    }

    x = p_image->x0;
    y = p_image->y0;
    tx = p_image->x1 - p_image->x0;
    ty = p_image->y1 - p_image->y0;
    tw = tx / p_cp->tw;
    th = ty / p_cp->th;
    if (p_tileno >= p_cp->tw * p_cp->th) {
        return; /* invalid tile index */
    }

    x += (p_tileno % p_cp->tw) * tw;
    y += (p_tileno / p_cp->tw) * th;
    tx = x + tw;
    ty = y + th;
    if (tx > (OPJ_UINT32)p_image->x1) {
        tx = p_image->x1;
    }
    if (ty > (OPJ_UINT32)p_image->y1) {
        ty = p_image->y1;
    }

    *p_tx0 = (OPJ_INT32)x;
    *p_ty0 = (OPJ_INT32)y;
    *p_tx1 = (OPJ_INT32)tx;
    *p_ty1 = (OPJ_INT32)ty;
    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}
